import { useMemo } from 'react'
import { faceSVG } from '../lib/nephraFace'

// The markup is generated by our own faceSVG, never from user input.
// display:contents lets the svg size itself against the parent (.orb, .mini, .who).
export default function NephraFace({ emotion = 'happy', size, title = '' }) {
  const html = useMemo(() => faceSVG(emotion, { size, title }), [emotion, size, title])
  return <span className="contents" dangerouslySetInnerHTML={{ __html: html }} />
}
